// qaRescanStartUpstream starts the stub; its URL is what the server subprocess
// env hands the plugin via MELLIFERA_SHIKIMORI_UPSTREAM.
func qaRescanStartUpstream(t *testing.T) *qaRescanUpstream {
	t.Helper()
	s := &qaRescanUpstream{}
	mux := http.NewServeMux()
	mux.HandleFunc(qaRescanUpstreamSearch, func(w http.ResponseWriter, r *http.Request) {
		s.record(r)
		list, ok := qaRescanSearchList[r.URL.Query().Get("search")]
		if !ok {
			http.NotFound(w, r)
			return
		}
		qaRescanWriteJSON(t, w, list)
	})
	mux.HandleFunc(qaRescanUpstreamSearch+"/", func(w http.ResponseWriter, r *http.Request) {
		s.record(r)
		e, ok := qaRescanByID[strings.TrimPrefix(r.URL.Path, qaRescanUpstreamSearch+"/")]
		if !ok {
			http.NotFound(w, r)
			return
		}
		qaRescanWriteJSON(t, w, e)
	})
	s.srv = httptest.NewServer(mux)
	s.baseURL = s.srv.URL
	t.Cleanup(s.srv.Close)
	return s
}

func (s *qaRescanUpstream) record(r *http.Request) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.seen = append(s.seen, qaRescanUpstreamReq{
		method: r.Method, path: r.URL.Path, query: r.URL.RawQuery,
		ua: r.Header.Get("User-Agent"),
	})
}

func (s *qaRescanUpstream) requests() []qaRescanUpstreamReq {
	s.mu.Lock()
	defer s.mu.Unlock()
	return append([]qaRescanUpstreamReq(nil), s.seen...)
}

func qaRescanWriteJSON(t *testing.T, w http.ResponseWriter, v any) {
	t.Helper()
	w.Header().Set("Content-Type", "application/json")
	if err := json.NewEncoder(w).Encode(v); err != nil {
		t.Errorf("stub write: %v", err)
	}
}

