// qaRescanRow is one persisted row at snapshot time: its stable id, its wire
// status, and its full decoded document (the deep-equal basis).
type qaRescanRow struct {
	id     string
	status string
	doc    map[string]any
}

// qaRescanSnap snapshots every row of one library, keyed by relative path
// (order-independent; the series identity IS the relative path).
type qaRescanSnap struct {
	Series map[string]qaRescanRow
	Items  map[string]qaRescanRow
}

// qaRescanSnapshot captures the library's settled rows. It fatals unless every
// row reads ready — the callers settle FIRST (qaSerialWaitSettled), so a
// non-ready row here is a harness bug, not an assertion.
func qaRescanSnapshot(t *testing.T, c *http.Client, baseURL, token string, libID int64) qaRescanSnap {
	t.Helper()
	snap := qaRescanSnap{Series: map[string]qaRescanRow{}, Items: map[string]qaRescanRow{}}
	for _, sr := range qaSerialListSeries(t, c, baseURL, token, libID) {
		var doc map[string]any
		if err := json.Unmarshal(sr.Document, &doc); err != nil {
			t.Fatalf("snapshot: decode series %q document: %v", sr.RelativePath, err)
		}
		if sr.Status != "ready" {
			t.Fatalf("snapshot: series %q status = %q, want ready (settle must precede the snapshot)", sr.RelativePath, sr.Status)
		}
		snap.Series[sr.RelativePath] = qaRescanRow{id: sr.ID, status: sr.Status, doc: doc}
	}
	for _, it := range listItems(t, c, baseURL, token, libID) {
		var doc map[string]any
		if err := json.Unmarshal(it.Document, &doc); err != nil {
			t.Fatalf("snapshot: decode item %q document: %v", it.RelativePath, err)
		}
		if it.Status != "ready" {
			t.Fatalf("snapshot: item %q status = %q, want ready (settle must precede the snapshot)", it.RelativePath, it.Status)
		}
		snap.Items[it.RelativePath] = qaRescanRow{id: it.ID, status: it.Status, doc: doc}
	}
	if len(snap.Series) != 2 || len(snap.Items) != 3 {
		t.Fatalf("snapshot: %d series / %d items, want 2/3 (Lantern Bay + Winter Tracker; 3 episodes)",
			len(snap.Series), len(snap.Items))
	}
	return snap
}

// qaRescanEnrichStats is the enrich-queue snapshot from GET /admin/status (the
// real server wires enrich.Stats into that endpoint).
type qaRescanEnrichStats struct {
	Pending  int `json:"pending"`
	InFlight int `json:"in_flight"`
	Done     int `json:"done"`
	Failed   int `json:"failed"`
}

// qaRescanDeriveItems is the exact number of work items one derive pass
// enqueues for this fixture: every row (2 series + 3 episodes) carries exactly
// one contractually namespace-less pending pair (frame-grabber on series rows,
// shikimori on episode rows — skipped outcomes write no ledger row, so the
// pair is pending on every pass), and deriveLibrary enqueues one work item per
// row with pending work; statDone counts each such item when it settles ready.
const qaRescanDeriveItems = 5

// qaRescanEnrichProcessed reads the cumulative processed counter (done+failed —
// completed workItem runs only).
func qaRescanEnrichProcessed(t *testing.T, c *http.Client, baseURL, token string) int {
	t.Helper()
	var resp struct {
		Enrich qaRescanEnrichStats `json:"enrich"`
	}
	if status := doRequest(t, c, http.MethodGet, baseURL+"/api/v1/admin/status", token, nil, &resp); status != http.StatusOK {
		t.Fatalf("admin status: HTTP %d, want 200", status)
	}
	return resp.Enrich.Done + resp.Enrich.Failed
}

// qaRescanDrainEnrich waits for the enrich queue's own liveness counters
// (GET /admin/status) to report the derive pass fully settled: nothing pending,
// nothing in flight, and at least baseline work items processed. This is the
// amended scenario's "queue settles", which qaSerialWaitSettled alone cannot
// see: a rescan's derive pass only appends truthful skipped _stages entries and
// never moves an already-ready row's status, so a status-only wait races the
// pass. Sound because statInFlight is released only after the work item's
// persistRow (internal/enrich/queue.go workItem), so idle counters imply every
// enqueued pass's document writes are durable. Bounded by qaSerialDrainTimeout.
func qaRescanDrainEnrich(t *testing.T, c *http.Client, baseURL, token string, baseline int) {
	t.Helper()
	deadline := time.Now().Add(qaSerialDrainTimeout)
	for {
		var resp struct {
			Enrich qaRescanEnrichStats `json:"enrich"`
		}
		if status := doRequest(t, c, http.MethodGet, baseURL+"/api/v1/admin/status", token, nil, &resp); status != http.StatusOK {
			t.Fatalf("admin status: HTTP %d, want 200", status)
		}
		st := resp.Enrich
		if st.Pending == 0 && st.InFlight == 0 && st.Done+st.Failed >= baseline {
			return
		}
		if time.Now().After(deadline) {
			t.Fatalf("enrich queue not settled within %s: pending=%d in_flight=%d done=%d failed=%d, want idle with processed >= %d",
				qaSerialDrainTimeout, st.Pending, st.InFlight, st.Done, st.Failed, baseline)
		}
		time.Sleep(probeInterval)
	}
}

// qaRescanAssertCarried asserts one untouched row survived a rescan with its
// identity, ready status, and byte-equivalent document — per the AMENDED
// scenario (probe 0149c43a097537b4): sources, _provenance, _view, parsed,
// ffprobe, and every other non-_stages field deep-equal the snapshot
// verbatim, and _stages is byte-equivalent as a PREFIX plus exactly the
// truthful skipped entries the enrich queue appends per derive pass for the
// contractually namespace-less plugin×row shapes (frame-grabber on series,
// shikimori on episodes): one {stage metadata_source, plugin_id, status
// skipped, advanced_to ready} entry per scan, appended at the tail in
// appendStage order with fresh started_at/finished_at stamps. appended lists
// the expected plugin ids of those entries in order; empty = _stages must be
// byte-identical.
func qaRescanAssertCarried(t *testing.T, phase, rel string, before, after qaRescanRow, appended ...string) {
	t.Helper()
	if after.id != before.id {
		t.Errorf("%s: %q row id changed %q -> %q (identity must be stable)", phase, rel, before.id, after.id)
	}
	if after.status != "ready" {
		t.Errorf("%s: %q status = %q, want ready preserved", phase, rel, after.status)
	}
	qaRescanAssertStages(t, phase, rel, before.doc, after.doc, appended...)
	withoutStages := func(doc map[string]any) map[string]any {
		t.Helper()
		kept := make(map[string]any, len(doc))
		for k, v := range doc {
			if k != "_stages" {
				kept[k] = v
			}
		}
		return kept
	}
	if !deepEqualJSON(withoutStages(before.doc), withoutStages(after.doc)) {
		b, _ := json.Marshal(withoutStages(before.doc))
		a, _ := json.Marshal(withoutStages(after.doc))
		t.Errorf("%s: %q document drifted across the rescan outside the appended _stages entries (want verbatim carry):\nbefore: %s\nafter:  %s", phase, rel, b, a)
	}
}

// qaRescanAssertStages asserts the amended-scenario _stages delta exactly:
// the post-rescan list is the snapshot's list (byte-equal prefix) plus
// len(appended) truthful skipped entries, each pinned to the observed
// appendStage shape for its plugin (stage metadata_source, status skipped,
// advanced_to ready, non-empty started_at/finished_at — the stamps are
// time-dependent, so they are presence-asserted).
func qaRescanAssertStages(t *testing.T, phase, rel string, before, after map[string]any, appended ...string) {
	t.Helper()
	bStages, _ := before["_stages"].([]any)
	aStages, _ := after["_stages"].([]any)
	if len(aStages) != len(bStages)+len(appended) {
		t.Errorf("%s: %q _stages grew %d -> %d, want exactly +%d (the truthful skipped entries %v one derive pass appends)",
			phase, rel, len(bStages), len(aStages), len(appended), appended)
		return
	}
	for i, e := range bStages {
		if !deepEqualJSON(e, aStages[i]) {
			eb, _ := json.Marshal(e)
			ab, _ := json.Marshal(aStages[i])
			t.Errorf("%s: %q _stages[%d] drifted (want verbatim carry):\nbefore: %s\nafter:  %s", phase, rel, i, eb, ab)
		}
	}
	for i, plugin := range appended {
		idx := len(bStages) + i
		e, _ := aStages[idx].(map[string]any)
		if e == nil {
			t.Errorf("%s: %q _stages[%d] is not an object: %v", phase, rel, idx, aStages[idx])
			continue
		}
		gotStage, gotPlugin, gotStatus, gotAdvanced := asyncStr(e, "stage"), asyncStr(e, "plugin_id"), asyncStr(e, "status"), asyncStr(e, "advanced_to")
		if gotStage != "metadata_source" || gotPlugin != plugin || gotStatus != "skipped" || gotAdvanced != "ready" {
			eb, _ := json.Marshal(e)
			t.Errorf("%s: %q _stages[%d] = %s, want the truthful appended entry {stage metadata_source, plugin_id %q, status skipped, advanced_to ready}",
				phase, rel, idx, eb, plugin)
		}
		if asyncStr(e, "started_at") == "" || asyncStr(e, "finished_at") == "" {
			t.Errorf("%s: %q _stages[%d] lacks started_at/finished_at stamps: %v", phase, rel, idx, e)
		}
	}
}

// qaRescanFetchedAt reads one field's provenance fetched_at stamp.
func qaRescanFetchedAt(doc map[string]any, field string) string {
	prov, _ := doc["_provenance"].(map[string]any)
	entry, _ := prov[field].(map[string]any)
	s, _ := entry["fetched_at"].(string)
	return s
}

// qaRescanSearches counts a request list by its search-query term.
func qaRescanSearches(t *testing.T, reqs []qaRescanUpstreamReq) map[string]int {
	t.Helper()
	out := map[string]int{}
	for i, r := range reqs {
		q, err := url.ParseQuery(r.query)
		if err != nil {
			t.Fatalf("request %d: bad query %q: %v", i, r.query, err)
		}
		out[q.Get("search")]++
	}
	return out
}

// qaRescanAssertAllSearches pins the upstream contract over the WHOLE run: every
// recorded request is a bounded-size GET search carrying the application
// User-Agent — the by-id (anchored re-enrichment) endpoint stayed unreached.
func qaRescanAssertAllSearches(t *testing.T, reqs []qaRescanUpstreamReq) {
	t.Helper()
	for i, r := range reqs {
		if r.method != http.MethodGet || r.path != qaRescanUpstreamSearch {
			t.Errorf("request %d: %s %s, want GET %s (by-id is anchored re-enrichment territory — none expected)", i, r.method, r.path, qaRescanUpstreamSearch)
			continue
		}
		if !strings.HasPrefix(r.ua, "mellifera/") {
			t.Errorf("request %d: User-Agent = %q, want the mellifera application UA (never a library default)", i, r.ua)
		}
		q, err := url.ParseQuery(r.query)
		if err != nil {
			t.Errorf("request %d: bad query %q: %v", i, r.query, err)
			continue
		}
		if q.Get("limit") == "" {
			t.Errorf("request %d: search query %q carries no bounded page size", i, r.query)
		}
	}
}

// TestRescanPreservesEnrichmentJoint is the Tier-1 joint contract of
// preserve-enrichment-rescan: the REAL scan→persist→queue→enrich chain keeps
// derived enrichment across an unchanged rescan (zero derived work) and
// re-derives exactly the changed identity through the real chain (stub-attributed
// work), per-row.
func TestRescanPreservesEnrichmentJoint(t *testing.T) {
	if testing.Short() {
		t.Skip("QA rescan preservation joint e2e: skips under -short (builds binaries + subprocesses)")
	}
	if _, err := exec.LookPath("ffprobe"); err != nil {
		t.Skip("ffprobe not on PATH — episodes cannot be probed; skipping (INV4: optional binary)")
	}

	tmp := t.TempDir()
	serverBin := buildBinary(t, tmp, "qa-rescan-server", "./cmd/mellifera")
	baseScannerBin := buildBinary(t, tmp, "qa-rescan-basescanner", "./plugins/base-scanner")
	tvParserBin := buildBinary(t, tmp, "qa-rescan-tvparser", "./plugins/tv-parser")
	imageEnricherBin := buildBinary(t, tmp, "qa-rescan-imageenricher", "./plugins/image-enricher")
	serialScannerBin := buildBinary(t, tmp, "qa-rescan-scanner", "./plugins/serial-scanner")
	serialParserBin := buildBinary(t, tmp, "qa-rescan-parser", "./plugins/serial-parser")
	frameGrabberBin := buildBinary(t, tmp, "qa-rescan-grabber", "./plugins/frame-grabber")

	// HERMETIC: the stub upstream starts FIRST (its URL feeds the server env's
	// MELLIFERA_SHIKIMORI_UPSTREAM) and every plugin binary is pinned (the
	// qaSerialStartServer harness).
	up := qaRescanStartUpstream(t)
	srv := qaSerialStartServer(t, qaSerialServerBins{
		server: serverBin, baseScanner: baseScannerBin, tvParser: tvParserBin,
		imageEnricher: imageEnricherBin, serialScanner: serialScannerBin,
		serialParser: serialParserBin, frameGrabber: frameGrabberBin,
	}, up.baseURL, tmp, "qa-rescan-admin-token")
	client := &http.Client{Timeout: httpTimeout}
	token := "qa-rescan-admin-token"

	root := qaRescanWriteFixtures(t)
	lib := qaSerialCreateLibrary(t, client, srv.baseURL, token, root, "QA Rescan Preservation")

	res := scanLibrary(t, client, srv.baseURL, token, lib)
	if res.Discovered != 5 || res.Persisted != 5 {
		t.Fatalf("first scan: discovered=%d persisted=%d, want 5/5 (2 serial records + 3 episodes); warnings=%v",
			res.Discovered, res.Persisted, res.Warnings)
	}
	if len(res.Warnings) != 0 {
		t.Errorf("first scan: warnings = %v, want none (clean fixture library)", res.Warnings)
	}

	// Drain the first scan to a fully settled (ready) library, then snapshot
	// every row and the stub's request list — the baseline both subtests lean on.
	qaSerialWaitSettled(t, client, srv.baseURL, token, lib)
	snap := qaRescanSnapshot(t, client, srv.baseURL, token, lib)

	// Baseline sanity: the enrichment actually landed (the subtests prove what a
	// rescan does TO this state, so the state itself must be the enriched one).
	for rel, row := range snap.Series {
		sources, _ := row.doc["sources"].(map[string]any)
		if sources["serial-parser"] == nil || sources["shikimori"] == nil {
			t.Fatalf("baseline: series %q sources = %v, want serial-parser + shikimori", rel, sources)
		}
		if qaRescanFetchedAt(row.doc, "title") == "" {
			t.Fatalf("baseline: series %q lacks _provenance.title.fetched_at", rel)
		}
	}
	for _, rel := range []string{qaRescanEpLantern1, qaRescanEpLantern2, qaRescanEpWinter} {
		row := snap.Items[rel]
		sources, _ := row.doc["sources"].(map[string]any)
		if sources["serial-parser"] == nil {
			t.Fatalf("baseline: item %q sources = %v, want serial-parser", rel, sources)
		}
		if qaRescanFetchedAt(row.doc, "season") == "" {
			t.Fatalf("baseline: item %q lacks _provenance.season.fetched_at", rel)
		}
	}
	reqs0 := up.requests()
	if len(reqs0) != 2 {
		t.Fatalf("baseline: stub recorded %d requests, want 2 (one search per series row): %+v", len(reqs0), reqs0)
	}

	// --- subtest preserved: the UNCHANGED rescan derives ZERO enrichment ---
	//
	// The re-scan refreshes the base (parsed + ffprobe) and carries every prior
	// derived namespace forward verbatim (tier A parsed-equal, tier B
	// ffprobe-equal); the queue performs no enrichment — no stub request, no
	// provenance touch. Its only writes are the truthful skipped entries the
	// amended scenario (probe 0149c43a097537b4) budgets: exactly one per derive
	// pass per row for the contractually namespace-less shapes (frame-grabber
	// on series, shikimori on episodes), asserted entry-exact below.
	drain0 := qaRescanEnrichProcessed(t, client, srv.baseURL, token)
	t.Run("preserved", func(t *testing.T) {
		res2 := scanLibrary(t, client, srv.baseURL, token, lib)
		if res2.Discovered != res.Discovered || res2.Persisted != res.Persisted {
			t.Errorf("unchanged rescan: discovered=%d persisted=%d, want %d/%d (idempotent)",
				res2.Discovered, res2.Persisted, res.Discovered, res.Persisted)
		}
		qaSerialWaitSettled(t, client, srv.baseURL, token, lib)
		qaRescanDrainEnrich(t, client, srv.baseURL, token, drain0+qaRescanDeriveItems)
		after := qaRescanSnapshot(t, client, srv.baseURL, token, lib)

		for rel, before := range snap.Series {
			qaRescanAssertCarried(t, "preserved", rel, before, after.Series[rel], "frame-grabber")
		}
		for rel, before := range snap.Items {
			qaRescanAssertCarried(t, "preserved", rel, before, after.Items[rel], "shikimori")
		}

		// The no-work proof at the stub: not one new upstream request — the
		// queue derived zero work for preserved namespaces.
		reqs1 := up.requests()
		if len(reqs1) != len(reqs0) {
			t.Errorf("unchanged rescan: stub recorded %d requests, want %d (the queue must derive zero work for an unchanged rescan):\nbefore: %+v\nafter:  %+v",
				len(reqs1), len(reqs0), reqs0, reqs1)
		}
		beforeSearches := qaRescanSearches(t, reqs0)
		afterSearches := qaRescanSearches(t, reqs1)
		for title, n := range beforeSearches {
			if afterSearches[title] != n {
				t.Errorf("unchanged rescan: search %q count %d -> %d (want unchanged)", title, n, afterSearches[title])
			}
		}
	})

	// --- subtest rederived: the parsed-identity change re-derives through the
	// real chain, everything else stays carried ---
	//
	// Renaming the matched sidecar out of E01's SxxExx match changes BOTH
	// changed rows' parsed identity in ONE scan (episode sidecars 1 -> 0;
	// series series_sidecars 0 -> 1): scan drops their derived namespaces
	// (tier A) and the queue re-derives them through serial-parser +
	// shikimori — the stub records exactly one NEW search attributable to the
	// re-derived series — while the untouched rows keep their carried
	// namespaces byte-equivalent.
	t.Run("rederived", func(t *testing.T) {
		// Timestamp-separation guard: _provenance fetched_at stamps are
		// RFC3339 (second resolution). Guaranteeing >1s between the snapshot's
		// drain and the re-derivation makes "fetched_at is strictly later" a
		// DETERMINISTIC rewrite proof — a carried namespace would keep the old
		// stamp byte-identical (the preserved subtest pins that equivalence).
		// This is a property guarantee, not a synchronization wait.
		time.Sleep(1100 * time.Millisecond)

		if err := os.Rename(filepath.Join(root, qaRescanSubMatched), filepath.Join(root, qaRescanSubMoved)); err != nil {
			t.Fatalf("rename matched sidecar %s -> %s: %v", qaRescanSubMatched, qaRescanSubMoved, err)
		}

		drain1 := qaRescanEnrichProcessed(t, client, srv.baseURL, token)
		res3 := scanLibrary(t, client, srv.baseURL, token, lib)
		if res3.Discovered != 5 || res3.Persisted != 5 {
			t.Errorf("mutation rescan: discovered=%d persisted=%d, want 5/5 (same rows, changed facts); warnings=%v",
				res3.Discovered, res3.Persisted, res3.Warnings)
		}
		qaSerialWaitSettled(t, client, srv.baseURL, token, lib)
		qaRescanDrainEnrich(t, client, srv.baseURL, token, drain1+qaRescanDeriveItems)
		after := qaRescanSnapshot(t, client, srv.baseURL, token, lib)

		// The stub attribution proof FIRST (it grounds "re-derived through the
		// real chain"): exactly one new request, and it is the re-derived
		// serial's search — Winter Tracker derived no work.
		reqs2 := up.requests()
		if len(reqs2) != len(reqs0)+1 {
			t.Errorf("mutation rescan: stub recorded %d requests, want exactly %d (+1 for the re-derived series):\nbefore: %+v\nafter:  %+v",
				len(reqs2), len(reqs0)+1, reqs0, reqs2)
		}
		searches := qaRescanSearches(t, reqs2)
		wantSearches := map[string]int{
			qaRescanLanternTitle: 2, // first drain + the re-derivation
			qaRescanWinterTitle:  1, // first drain only — untouched
		}
		for title, n := range wantSearches {
			if searches[title] != n {
				t.Errorf("mutation rescan: search %q seen %d times, want %d; searches seen: %v", title, searches[title], n, searches)
			}
		}
		qaRescanAssertAllSearches(t, reqs2)

		// The changed SERIES row: namespaces were dropped at the re-scan and
		// freshly re-written by the real chain (a carried namespace would be
		// byte-identical to the snapshot — timestamps included).
		lbBefore := snap.Series[qaRescanDirLantern]
		lbAfter := after.Series[qaRescanDirLantern]
		if lbAfter.status != "ready" {
			t.Errorf("changed series %q status = %q, want ready after the re-derivation settles", qaRescanDirLantern, lbAfter.status)
		}
		lbSources, _ := lbAfter.doc["sources"].(map[string]any)
		parserNS, _ := lbSources["serial-parser"].(map[string]any)
		if asyncStr(parserNS, "title") != qaRescanLanternTitle || asyncInt(parserNS, "season") != 1 {
			t.Errorf("changed series: sources.serial-parser = %v, want {title:%q season:1} freshly re-derived", parserNS, qaRescanLanternTitle)
		}
		shikNS, _ := lbSources["shikimori"].(map[string]any)
		shikTitle, _ := shikNS["title"].(map[string]any)
		if asyncStr(shikTitle, "romaji") != "Lantern Bay" || asyncStr(shikTitle, "russian") != "Фонарная бухта" || asyncStr(shikNS, "kind") != "tv" {
			t.Errorf("changed series: sources.shikimori = %v, want the stub candidate re-fetched through the real chain", shikNS)
		}
		ids, _ := lbAfter.doc["identifiers"].(map[string]any)
		if got, _ := ids["shikimori_id"].(float64); int(got) != 801 {
			t.Errorf("changed series: identifiers.shikimori_id = %v, want 801 re-anchored by the fresh chain", ids["shikimori_id"])
		}
		// The fresh BASE facts: the renamed sidecar now rides the series as a
		// serial-level sidecar (match_basis null) — the identity that changed.
		lbParsed, _ := lbAfter.doc["parsed"].(map[string]any)
		seriesSidecars, _ := lbParsed["series_sidecars"].([]any)
		if len(seriesSidecars) != 1 {
			t.Fatalf("changed series: parsed.series_sidecars = %v, want exactly the renamed sidecar", seriesSidecars)
		}
		sc, _ := seriesSidecars[0].(map[string]any)
		if qaSerialStr(sc, "relative_path") != qaRescanSubMoved || qaSerialStr(sc, "kind") != "subtitle" || qaSerialStr(sc, "language") != "" || sc["match_basis"] != nil {
			t.Errorf("changed series: series_sidecars[0] = %v, want {%q subtitle language=\"\" match_basis null} (serial-level after the rename)", sc, qaRescanSubMoved)
		}
		// Freshness, deterministic via the timestamp-separation guard.
		if got, before := qaRescanFetchedAt(lbAfter.doc, "title"), qaRescanFetchedAt(lbBefore.doc, "title"); got <= before {
			t.Errorf("changed series: _provenance.title.fetched_at = %q, want strictly later than the carried stamp %q (namespaces must be re-written, not carried)", got, before)
		}
		if su := asyncStr(lbAfter.doc["_provenance"].(map[string]any)["title"].(map[string]any), "source_url"); !strings.HasPrefix(su, up.baseURL) {
			t.Errorf("changed series: provenance source_url = %q, want the stub origin %q", su, up.baseURL)
		}
		lbStages, _ := lbAfter.doc["_stages"].([]any)
		if !asyncStageHas(decodeStages(t, lbStages), "serial-parser", "ok") ||
			!asyncStageHas(decodeStages(t, lbStages), "shikimori", "ok") ||
			!asyncStageHas(decodeStages(t, lbStages), "frame-grabber", "skipped") {
			t.Errorf("changed series: _stages = %v, want fresh {serial-parser ok} + {shikimori ok} + {frame-grabber skipped}", lbStages)
		}

		// The changed EPISODE row: sidecars fact gone from its parsed identity,
		// parser namespace re-written by the chain, no shikimori leak (the
		// episode-shape dispatch holds on a real re-derivation too).
		e1Before := snap.Items[qaRescanEpLantern1]
		e1After := after.Items[qaRescanEpLantern1]
		if e1After.status != "ready" {
			t.Errorf("changed item %q status = %q, want ready after the re-derivation settles", qaRescanEpLantern1, e1After.status)
		}
		e1Parsed, _ := e1After.doc["parsed"].(map[string]any)
		if got := qaSerialSidecarFacts(e1Parsed, "sidecars"); len(got) != 0 {
			t.Errorf("changed item: parsed.sidecars = %v, want none (the sidecar left its SxxExx match — the parsed identity that changed)", got)
		}
		if got := asyncStr(e1Parsed, "series_relative_path"); got != qaRescanDirLantern {
			t.Errorf("changed item: parsed.series_relative_path = %q, want %q (same row identity)", got, qaRescanDirLantern)
		}
		e1Sources, _ := e1After.doc["sources"].(map[string]any)
		e1Parser, _ := e1Sources["serial-parser"].(map[string]any)
		if asyncInt(e1Parser, "season") != 1 || asyncInt(e1Parser, "episode") != 1 {
			t.Errorf("changed item: sources.serial-parser = %v, want {season:1 episode:1} freshly re-derived", e1Parser)
		}
		if _, leak := e1Sources["shikimori"]; leak {
			t.Errorf("changed item: sources.shikimori leaked onto an episode document: %v", e1Sources["shikimori"])
		}
		if got, before := qaRescanFetchedAt(e1After.doc, "season"), qaRescanFetchedAt(e1Before.doc, "season"); got <= before {
			t.Errorf("changed item: _provenance.season.fetched_at = %q, want strictly later than the carried stamp %q (namespaces must be re-written, not carried)", got, before)
		}
		e1Stages, _ := e1After.doc["_stages"].([]any)
		if !asyncStageHas(decodeStages(t, e1Stages), "serial-parser", "ok") {
			t.Errorf("changed item: _stages = %v, want a fresh {serial-parser ok} stage", e1Stages)
		}

		// The untouched rows: carried documents, still ready. Against the
		// shared pre-rescan snapshot their _stages delta is TWO derive passes
		// (preserved's rescan + this one), so two truthful skipped entries
		// each — everything else must still compare byte-equivalent.
		qaRescanAssertCarried(t, "rederived", qaRescanDirWinter, snap.Series[qaRescanDirWinter], after.Series[qaRescanDirWinter], "frame-grabber", "frame-grabber")
		qaRescanAssertCarried(t, "rederived", qaRescanEpLantern2, snap.Items[qaRescanEpLantern2], after.Items[qaRescanEpLantern2], "shikimori", "shikimori")
		qaRescanAssertCarried(t, "rederived", qaRescanEpWinter, snap.Items[qaRescanEpWinter], after.Items[qaRescanEpWinter], "shikimori", "shikimori")
	})
}

// decodeStages converts a decoded _stages JSON list into the shape
// asyncStageHas reads (the snapshot path decodes documents as generic maps, so
// the stage list arrives as []any).
func decodeStages(t *testing.T, stages []any) []map[string]any {
	t.Helper()
	out := make([]map[string]any, 0, len(stages))
	for _, s := range stages {
		m, ok := s.(map[string]any)
		if !ok {
			t.Fatalf("decode _stages entry %v: not an object", s)
		}
		out = append(out, m)
	}
	return out
}
